<template><main class="hh-page billing-document"><router-link :to="back" class="hh-back-link"><i class="ph ph-arrow-left"></i> Volver</router-link><div v-if="loading" class="state"><span class="spinner-border text-primary"></span></div><div v-else-if="error&&!record" class="alert alert-danger mt-3">{{error}}</div><template v-else-if="record"><section class="document-hero"><div><small>{{type==='invoice'?'FACTURA':'GLOSA'}} #{{record.id||route.params.id}}</small><h1>{{record.numero_factura||record.paciente||record.nombre||title}}</h1><p>{{record.pagador||record.tercero||record.descripcion||'Gestión de facturación'}}</p></div><span>{{record.estado||'PENDIENTE'}}</span></section><div v-if="error" class="alert alert-danger mt-3">{{error}}</div><section class="document-actions"><div><small>ACCIONES DISPONIBLES</small><h2>{{title}}</h2></div><div v-if="type==='invoice'"><button class="btn btn-outline-primary" :disabled="saving" @click="execute('transmit')">Transmitir</button><button class="btn btn-outline-primary" :disabled="saving" @click="open('file')">Radicar</button><button class="btn btn-outline-warning" :disabled="saving" @click="open('gloss')">Registrar glosa</button><button class="btn btn-success" :disabled="saving" @click="open('payment')">Registrar pago</button></div><div v-else><button class="btn btn-primary" :disabled="saving" @click="open('answer')">Responder glosa</button></div></section><section class="document-card"><header><h2>Información del registro</h2></header><div class="data-grid"><article v-for="entry in entries" :key="entry[0]"><small>{{label(entry[0])}}</small><strong>{{format(entry[1],entry[0])}}</strong></article></div></section></template><Teleport to="body"><div v-if="action" class="document-layer" @mousedown.self="close"><section class="document-modal"><header><h3>{{actionTitles[action]}}</h3><button class="btn-close" @click="close"></button></header><form @submit.prevent="execute(action)"><div class="modal-body"><div v-if="modalError" class="alert alert-danger">{{modalError}}</div><label class="form-label">{{action==='payment'?'Valor':'Observación / referencia'}} *</label><input v-if="action==='payment'" v-model.number="form.value" type="number" min="1" class="form-control" required><textarea v-else v-model.trim="form.note" class="form-control" rows="3" required></textarea></div><footer><button type="button" class="btn btn-outline-secondary" @click="close">Cancelar</button><button class="btn btn-primary" :disabled="saving"><span v-if="saving" class="spinner-border spinner-border-sm me-1"></span>{{saving?'Guardando…':'Confirmar'}}</button></footer></form></section></div></Teleport></main></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{obtenerMensajeError}from'@/services/api';import{consultarFactura,crearGlosa,listarRecursoFacturacion,radicarFactura,registrarPago,responderGlosa,transmitirFactura}from'@/services/facturacion';const route=useRoute(),type=computed(()=>route.meta.billingRecord||'invoice'),record=ref(null),loading=ref(true),saving=ref(false),error=ref(''),modalError=ref(''),action=ref(''),form=reactive({note:'',value:0}),title=computed(()=>type.value==='invoice'?'Control de factura':'Gestión de glosa'),back=computed(()=>type.value==='invoice'?'/facturacion/facturas':'/facturacion/glosas'),entries=computed(()=>Object.entries(record.value||{}).filter(([,v])=>['string','number','boolean'].includes(typeof v)).slice(0,30)),actionTitles={file:'Radicar factura',gloss:'Registrar glosa',payment:'Registrar pago',answer:'Responder glosa'},label=k=>k.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()),format=(v,k)=>/valor|total|saldo/.test(k)?new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP'}).format(Number(v||0)):String(v);async function load(){loading.value=true;error.value='';try{const response=type.value==='invoice'?await consultarFactura(route.params.id):await listarRecursoFacturacion(`glosas/${route.params.id}`);record.value=response?.data||response}catch(e){error.value=obtenerMensajeError(e)}finally{loading.value=false}}function open(a){action.value=a;modalError.value='';Object.assign(form,{note:'',value:0})}function close(){if(!saving.value)action.value=''}async function execute(a){saving.value=true;modalError.value='';try{if(a==='transmit')await transmitirFactura(route.params.id);if(a==='file')await radicarFactura(route.params.id,{referencia:form.note});if(a==='gloss')await crearGlosa(route.params.id,{observacion:form.note});if(a==='payment')await registrarPago(route.params.id,{valor:Number(form.value)});if(a==='answer')await responderGlosa(route.params.id,{respuesta:form.note});action.value='';await load()}catch(e){(action.value?modalError:error).value=obtenerMensajeError(e)}finally{saving.value=false}}onMounted(load)</script>
<style scoped>.state{display:grid;place-items:center;padding:4rem}.document-hero{display:flex;align-items:center;justify-content:space-between;margin-top:1rem;padding:1.3rem 1.5rem;border-radius:1rem;background:linear-gradient(120deg,#123f68,#118aa6);color:#fff}.document-hero small,.document-hero h1,.document-hero p{display:block;margin:0}.document-hero h1{font-size:1.3rem}.document-hero>span{padding:.4rem .65rem;border-radius:20px;background:#ffffff24}.document-actions,.document-card{margin-top:1rem;padding:1rem;border:1px solid #dce6ec;border-radius:.8rem;background:#fff}.document-actions{display:flex;align-items:center;justify-content:space-between}.document-actions h2,.document-card h2{font-size:1rem}.document-actions>div:last-child{display:flex;gap:.45rem}.data-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:.6rem}.data-grid article{padding:.65rem;border-radius:.6rem;background:#f6f9fa}.data-grid small,.data-grid strong{display:block;overflow-wrap:anywhere}.data-grid small{color:#7b8996}.document-layer{position:fixed;inset:0;z-index:2100;display:grid;place-items:center;background:#071522bd}.document-modal{width:min(520px,calc(100% - 2rem));border-radius:1rem;background:#fff}.document-modal>header,.document-modal footer{display:flex;align-items:center;justify-content:space-between;padding:1rem;border-bottom:1px solid #e3e9ed}.document-modal .modal-body{padding:1rem}.document-modal footer{justify-content:flex-end;gap:.5rem;border-top:1px solid #e3e9ed;border-bottom:0}@media(max-width:700px){.data-grid{grid-template-columns:1fr}.document-actions{align-items:flex-start;flex-direction:column;gap:.7rem}}</style>
